<!DOCTYPE html>
<html lang="fr"><head><link rel="manifest" href="manifest.json"><meta name="theme-color" content="#198754"><meta charset="UTF-8"><title>Gestion des Chefs d'équipe - ONAS</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.2/dist/css/bootstrap.min.css" rel="stylesheet"><style>body{background:#f4f6f9}.main-content{padding:40px}.card-custom{border:none;border-radius:8px;box-shadow:0 2px 10px rgba(0,0,0,.1)}.table thead th{background:#212529;color:#fff}.btn-supprimer{background:#dc3545;color:#fff;border:0;padding:5px 12px;border-radius:4px}</style></head><body><div class="main-content"><div class="d-flex justify-content-between align-items-center mb-4"><h2>Gestion des Chefs d'équipe</h2><a href="index.php?action=dashboard_admin" class="btn btn-secondary">Retour</a></div><?php if(isset($_GET['msg'])):?><div class="alert alert-success"><?=htmlspecialchars($_GET['msg'],ENT_QUOTES,'UTF-8')?></div><?php endif;?><div class="row"><div class="col-md-4"><div class="card card-custom p-4"><h4>Ajouter Chef d'équipe</h4><form action="index.php?action=store_chef_equipe" method="POST"><input type="hidden" name="csrf_token" value="<?=htmlspecialchars(csrfToken(),ENT_QUOTES,'UTF-8')?>"><input name="nom" class="form-control mb-3" placeholder="Nom" required><input name="prenom" class="form-control mb-3" placeholder="Prénom" required><input name="matricule" class="form-control mb-3" placeholder="Matricule" required><input type="email" name="email" class="form-control mb-3" placeholder="Email" required><input type="password" name="password" class="form-control mb-3" minlength="8" placeholder="Mot de passe" required><input name="specialite" class="form-control mb-3" placeholder="Spécialité" required><button class="btn btn-primary w-100">Ajouter</button></form></div></div><div class="col-md-8"><div class="card card-custom p-4"><table class="table align-middle"><thead><tr><th>Matricule</th><th>Nom</th><th>Email</th><th>Spécialité</th><th>Action</th></tr></thead><tbody><?php if(isset($equipes)&&is_array($equipes)):foreach($equipes as $eq):if(($eq['role']??'')==='admin')continue;$id=(int)$eq['id_employer'];?><tr><td><?=htmlspecialchars($eq['matricule']??'',ENT_QUOTES,'UTF-8')?></td><td><?=htmlspecialchars($eq['nom']??'',ENT_QUOTES,'UTF-8')?></td><td><?=htmlspecialchars($eq['email']??'',ENT_QUOTES,'UTF-8')?></td><td><?=htmlspecialchars($eq['specialite']??'',ENT_QUOTES,'UTF-8')?></td><td><form action="index.php?action=supprimer_chef_equipe" method="POST" onsubmit="return confirm('Êtes-vous sûr ?')"><input type="hidden" name="csrf_token" value="<?=htmlspecialchars(csrfToken(),ENT_QUOTES,'UTF-8')?>"><input type="hidden" name="id" value="<?=$id?>"><button class="btn-supprimer">Supprimer</button></form></td></tr><?php endforeach;else:?><tr><td colspan="5" class="text-center text-muted">Aucune équipe à afficher.</td></tr><?php endif;?></tbody></table></div></div></div></div></body></html>